def read_conntrack_utilization() -> dict[str, float]:
    with open("/proc/sys/net/netfilter/nf_conntrack_count") as f:
        count = int(f.read().strip())
    with open("/proc/sys/net/netfilter/nf_conntrack_max") as f:
        limit = int(f.read().strip())
    return {"count": count, "max": limit, "utilization_pct": round((count / limit) * 100, 2)}

